def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    background = Counter(x for row in grid for x in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] != background]
        if len(cols) >= 2:
            for c in range(min(cols), max(cols) + 1):
                if out[r][c] == background:
                    out[r][c] = 3

    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] != background]
        if len(rows) >= 2:
            for r in range(min(rows), max(rows) + 1):
                if out[r][c] == background:
                    out[r][c] = 3

    return out
